import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

/**
 * Two sidebars: the developer path, and an internal section kept out of it.
 *
 * Entries are listed explicitly by doc ID rather than autogenerated, because
 * with `path: '../docs'` an autogenerated sidebar for `.` would sweep the
 * `internal/` documents into the developer navigation — which is the one thing
 * this structure exists to prevent. An explicit list also means a deleted page
 * fails the build here instead of silently disappearing from the nav.
 *
 * The landing page (`docs/README.md`) is deliberately in neither sidebar: it is
 * the site index.
 */
const sidebars: SidebarsConfig = {
  developers: [
    // The landing page is included so the front page shows the developer nav;
    // left out, `/` renders with no sidebar at all.
    { type: 'doc', id: 'README', label: 'Overview' },
    'quickstart',
    'authentication',
    'payments',
    'mcp',
    'api-reference',
  ],
  internal: [
    'internal/README',
    'internal/prd',
    'internal/fee-routing',
  ],
};

export default sidebars;
